fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    // Pre-allocate result vector with the same length as `indices`
    let mut result = Vec::with_capacity(indices.len());

    // For each position i, pick the element from row `indices[i]` and column i
    for (i, &idx) in indices.iter().enumerate() {
        // Convert idx to usize for indexing
        let row = idx as usize;
        // Since f64 is Copy, this fetches the value directly
        result.push(choices[row][i]);
    }

    result
}

