        // We expect:
        // result[0] = choices[2][0] = 30.0
        // result[1] = choices[0][1] = 11.0
        // result[2] = choices[1][2] = 22.0
        assert_eq!(choose(indices, choices), vec![30.0, 11.0, 22.0]);
